import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    words = data[1:n+1]

    if n < 2:
        original_len = sum(len(w) for w in words)
        if n > 1:
            original_len += n - 1
        else:
            original_len = sum(len(w) for w in words)
        print(original_len)
        return

    original_len = sum(len(w) for w in words) + (n - 1)

    min_len = original_len

    for start in range(n):
        for length in range(1, n - start + 1):
            end = start + length - 1
            if end >= n:
                break

            segment_words = words[start:end+1]
            segment_len = sum(len(w) for w in segment_words) + (length - 1)
            abbr_len = length

            count = 0
            positions = []

            for i in range(n - length + 1):
                match = True
                for k in range(length):
                    if words[i+k] != segment_words[k]:
                        match = False
                        break
                if match:
                    positions.append(i)
                    count += 1

            if count < 2:
                continue

            best_save = 0

            for i in range(len(positions)):
                for j in range(i + 1, len(positions)):
                    p1 = positions[i]
                    p2 = positions[j]

                    if p1 + length > p2:
                        continue

                    save = (segment_len - abbr_len) * 2
                    if save > best_save:
                        best_save = save

            current_len = original_len - best_save
            if current_len < min_len:
                min_len = current_len

    print(min_len)

if __name__ == "__main__":
    solve()
